function createBaseServerPacket(): ServerPacket {
  return { payload: undefined };
}

export const ServerPacket: MessageFns<ServerPacket> = {
  encode(message: ServerPacket, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    switch (message.payload?.$case) {
      case "worldSnapshot":
        WorldSnapshot.encode(message.payload.worldSnapshot, writer.uint32(10).fork()).join();
        break;
      case "worldDelta":
        WorldDelta.encode(message.payload.worldDelta, writer.uint32(18).fork()).join();
        break;
      case "chat":
        ChatEvent.encode(message.payload.chat, writer.uint32(26).fork()).join();
        break;
      case "whisper":
        WhisperEvent.encode(message.payload.whisper, writer.uint32(34).fork()).join();
        break;
      case "systemMessage":
        SystemMessage.encode(message.payload.systemMessage, writer.uint32(42).fork()).join();
        break;
      case "pong":
        PongEvent.encode(message.payload.pong, writer.uint32(50).fork()).join();
        break;
      case "welcome":
        WelcomeEvent.encode(message.payload.welcome, writer.uint32(58).fork()).join();
        break;
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): ServerPacket {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const previousRecursionDepth = (reader as any).__tsProtoDecodeDepth ?? 0;
    if (previousRecursionDepth >= 100) {
      throw new globalThis.Error("protobuf decode recursion limit exceeded");
    }
    (reader as any).__tsProtoDecodeDepth = previousRecursionDepth + 1;
    try {
      const end = length === undefined ? reader.len : reader.pos + length;
      const message = createBaseServerPacket();
      while (reader.pos < end) {
        const tag = reader.uint32();
        switch (tag >>> 3) {
          case 1: {
            if (tag !== 10) {
              break;
            }

            message.payload = { $case: "worldSnapshot", worldSnapshot: WorldSnapshot.decode(reader, reader.uint32()) };
            continue;
          }
          case 2: {
            if (tag !== 18) {
              break;
            }

            message.payload = { $case: "worldDelta", worldDelta: WorldDelta.decode(reader, reader.uint32()) };
            continue;
          }
          case 3: {
            if (tag !== 26) {
              break;
            }

            message.payload = { $case: "chat", chat: ChatEvent.decode(reader, reader.uint32()) };
            continue;
          }
          case 4: {
            if (tag !== 34) {
              break;
            }

            message.payload = { $case: "whisper", whisper: WhisperEvent.decode(reader, reader.uint32()) };
            continue;
          }
          case 5: {
            if (tag !== 42) {
              break;
            }

            message.payload = { $case: "systemMessage", systemMessage: SystemMessage.decode(reader, reader.uint32()) };
            continue;
          }
          case 6: {
            if (tag !== 50) {
              break;
            }

            message.payload = { $case: "pong", pong: PongEvent.decode(reader, reader.uint32()) };
            continue;
          }
          case 7: {
            if (tag !== 58) {
              break;
            }

            message.payload = { $case: "welcome", welcome: WelcomeEvent.decode(reader, reader.uint32()) };
            continue;
          }
        }
        if ((tag & 7) === 4 || tag === 0) {
          break;
        }
        reader.skip(tag & 7);
      }
      return message;
    } finally {
      (reader as any).__tsProtoDecodeDepth = previousRecursionDepth;
    }
  },

  fromJSON(object: any): ServerPacket {
    return {
      payload: isSet(object.worldSnapshot)
        ? { $case: "worldSnapshot", worldSnapshot: WorldSnapshot.fromJSON(object.worldSnapshot) }
        : isSet(object.world_snapshot)
        ? { $case: "worldSnapshot", worldSnapshot: WorldSnapshot.fromJSON(object.world_snapshot) }
        : isSet(object.worldDelta)
        ? { $case: "worldDelta", worldDelta: WorldDelta.fromJSON(object.worldDelta) }
        : isSet(object.world_delta)
        ? { $case: "worldDelta", worldDelta: WorldDelta.fromJSON(object.world_delta) }
        : isSet(object.chat)
        ? { $case: "chat", chat: ChatEvent.fromJSON(object.chat) }
        : isSet(object.whisper)
        ? { $case: "whisper", whisper: WhisperEvent.fromJSON(object.whisper) }
        : isSet(object.systemMessage)
        ? { $case: "systemMessage", systemMessage: SystemMessage.fromJSON(object.systemMessage) }
        : isSet(object.system_message)
        ? { $case: "systemMessage", systemMessage: SystemMessage.fromJSON(object.system_message) }
        : isSet(object.pong)
        ? { $case: "pong", pong: PongEvent.fromJSON(object.pong) }
        : isSet(object.welcome)
        ? { $case: "welcome", welcome: WelcomeEvent.fromJSON(object.welcome) }
        : undefined,
    };
  },

  toJSON(message: ServerPacket): unknown {
    const obj: any = {};
    if (message.payload?.$case === "worldSnapshot") {
      obj.worldSnapshot = WorldSnapshot.toJSON(message.payload.worldSnapshot);
    } else if (message.payload?.$case === "worldDelta") {
      obj.worldDelta = WorldDelta.toJSON(message.payload.worldDelta);
    } else if (message.payload?.$case === "chat") {
      obj.chat = ChatEvent.toJSON(message.payload.chat);
    } else if (message.payload?.$case === "whisper") {
      obj.whisper = WhisperEvent.toJSON(message.payload.whisper);
    } else if (message.payload?.$case === "systemMessage") {
      obj.systemMessage = SystemMessage.toJSON(message.payload.systemMessage);
    } else if (message.payload?.$case === "pong") {
      obj.pong = PongEvent.toJSON(message.payload.pong);
    } else if (message.payload?.$case === "welcome") {
      obj.welcome = WelcomeEvent.toJSON(message.payload.welcome);
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<ServerPacket>, I>>(base?: I): ServerPacket {
    return ServerPacket.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<ServerPacket>, I>>(object: I): ServerPacket {
    const message = createBaseServerPacket();
    switch (object.payload?.$case) {
      case "worldSnapshot": {
        if (object.payload?.worldSnapshot !== undefined && object.payload?.worldSnapshot !== null) {
          message.payload = {
            $case: "worldSnapshot",
            worldSnapshot: WorldSnapshot.fromPartial(object.payload.worldSnapshot),
          };
        }
        break;
      }
      case "worldDelta": {
        if (object.payload?.worldDelta !== undefined && object.payload?.worldDelta !== null) {
          message.payload = { $case: "worldDelta", worldDelta: WorldDelta.fromPartial(object.payload.worldDelta) };
        }
        break;
      }
      case "chat": {
        if (object.payload?.chat !== undefined && object.payload?.chat !== null) {
          message.payload = { $case: "chat", chat: ChatEvent.fromPartial(object.payload.chat) };
        }
        break;
      }
      case "whisper": {
        if (object.payload?.whisper !== undefined && object.payload?.whisper !== null) {
          message.payload = { $case: "whisper", whisper: WhisperEvent.fromPartial(object.payload.whisper) };
        }
        break;
      }
      case "systemMessage": {
        if (object.payload?.systemMessage !== undefined && object.payload?.systemMessage !== null) {
          message.payload = {
            $case: "systemMessage",
            systemMessage: SystemMessage.fromPartial(object.payload.systemMessage),
          };
        }
        break;
      }
      case "pong": {
        if (object.payload?.pong !== undefined && object.payload?.pong !== null) {
          message.payload = { $case: "pong", pong: PongEvent.fromPartial(object.payload.pong) };
        }
        break;
      }
      case "welcome": {
        if (object.payload?.welcome !== undefined && object.payload?.welcome !== null) {
          message.payload = { $case: "welcome", welcome: WelcomeEvent.fromPartial(object.payload.welcome) };
        }
        break;
      }
    }
    return message;
  },
};

type Builtin = Date | Function | Uint8Array | string | number | boolean | undefined;

export type DeepPartial<T> = T extends Builtin ? T
  : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends { $case: string } ? { [K in keyof Omit<T, "$case">]?: DeepPartial<T[K]> } & { $case: T["$case"] }
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
export type Exact<P, I extends P> = P extends Builtin ? P
  : P & { [K in keyof P]: Exact<P[K], I[K]> } & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}

export interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  fromJSON(object: any): T;
  toJSON(message: T): unknown;
  create<I extends Exact<DeepPartial<T>, I>>(base?: I): T;
  fromPartial<I extends Exact<DeepPartial<T>, I>>(object: I): T;
}
